css:
/* 玻璃拟态 2.0 · Glassmorphism 2.0
   与液态玻璃同为玻璃，但方向相反：浅色、分层更薄、噪点更细，
   背景是一张被虚化的彩色壁纸。面板靠 1px 白边和内外双向阴影立起来，不做大圆角浮岛。 */

html[data-theme] {
  color-scheme: light;
  --bg: #e9eef7;
  --ink: #16223a; --muted: #5b6a85; --dim:#5c6b87;
  --soft: #37475f; --meta: #5b6a85; --bright: #0b1220;
  --line: rgba(255, 255, 255, 0.72); --line2: rgba(22, 34, 58, 0.08);
  --accent:#3356ff; --accent2: #ff9ec7; --accentText: #ffffff;
  --good: #1e9c74; --warn: #c47a00;
  --glow1: rgba(77, 107, 255, 0.22); --glow2: rgba(255, 158, 199, 0.24);
  --panel: rgba(255, 255, 255, 0.45); --panel2: rgba(255, 255, 255, 0.62);
  --dock1: rgba(255, 255, 255, 0.62); --dock2: rgba(255, 255, 255, 0.42);
  --glass: rgba(255, 255, 255, 0.5);
  --track: rgba(22, 34, 58, 0.1); --scroll: rgba(22, 34, 58, 0.22); --coverbg: rgba(255, 255, 255, 0.6);
  --menu: rgba(255, 255, 255, 0.9); --menu1: rgba(255, 255, 255, 0.94); --menu2: rgba(247, 250, 255, 0.92); --chev: #6c7c99;
  --edge: rgba(255, 255, 255, 0.86); --edge2: rgba(77, 107, 255, 0.26);
  --hover: rgba(255, 255, 255, 0.68); --tick: rgba(22, 34, 58, 0.12);
  --inset: rgba(255, 255, 255, 0.9); --wordactive: #0b1220; --swborder: rgba(22, 34, 58, 0.18);
  --shadow-dock: 0 24px 60px -34px rgba(30, 46, 88, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  --serif: "SF Pro Display", "Segoe UI Variable Display", "PingFang SC", system-ui, sans-serif;
  --bottom: 138px;
  --shell-nav: rgba(255, 255, 255, 0.34); --shell-nav2: rgba(255, 255, 255, 0.18);
  --shell-navin: #16223a; --shell-navmuted: #5b6a85; --shell-navline: rgba(255, 255, 255, 0.6);
  --accent-ink:#3356ff;}

html[data-theme] body {
  background:
    radial-gradient(720px 520px at 8% 4%, #bcd4ff 0%, transparent 62%),
    radial-gradient(760px 540px at 92% 8%, #ffc9e0 0%, transparent 62%),
    radial-gradient(820px 600px at 50% 110%, #bff2e4 0%, transparent 66%),
    linear-gradient(160deg, #eef3fb, #e6ecf7 55%, #e9eef8);
}
/* 细噪点：比液态玻璃更轻，20% 透明度 */
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.35;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.35'/></svg>");
  mix-blend-mode: soft-light;
}

/* 侧栏：一层薄玻璃贴在壁纸上 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 24px 14px;
  border: 1px solid rgba(255, 255, 255, 0.72); border-radius: 26px;
  background: linear-gradient(170deg, rgba(255, 255, 255, 0.5), rgba(255, 255, 255, 0.22));
  box-shadow: 0 24px 60px -40px rgba(30, 46, 88, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(30px) saturate(150%); -webkit-backdrop-filter: blur(30px) saturate(150%);
}
html[data-theme] .brand { padding: 2px 8px 22px; border-bottom: 1px solid rgba(22, 34, 58, 0.08); margin-bottom: 14px; }
html[data-theme] .nav button { border-radius: 14px; color: #4c5c78; }
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.55); color: #16223a; }
html[data-theme] .nav button.active {
  background: rgba(255, 255, 255, 0.82); color: #16223a;
  box-shadow: 0 8px 22px -14px rgba(30, 46, 88, 0.5), inset 0 1px 0 #fff;
}

/* 顶栏：半透明白条 */
html[data-theme] .topbar {
  margin-top: 14px; padding: 0 18px; height: 64px;
  border: 1px solid rgba(255, 255, 255, 0.7); border-radius: 20px;
  background: rgba(255, 255, 255, 0.46);
  box-shadow: 0 18px 40px -34px rgba(30, 46, 88, 0.45), inset 0 1px 0 #fff;
  backdrop-filter: blur(26px) saturate(160%); -webkit-backdrop-filter: blur(26px) saturate(160%);
}
html[data-theme] .search-global { border: 1px solid rgba(255, 255, 255, 0.7); border-radius: 999px; background: rgba(255, 255, 255, 0.55); }
html[data-theme] .icon-btn { border: 1px solid rgba(255, 255, 255, 0.7); border-radius: 999px; background: rgba(255, 255, 255, 0.55); }

/* 首页 */
html[data-theme] .ledger-mast {
  margin-top: 20px; padding: 32px; border: 1px solid rgba(255, 255, 255, 0.78); border-radius: 28px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.3));
  box-shadow: 0 34px 70px -48px rgba(30, 46, 88, 0.55), inset 0 1px 0 #fff;
  backdrop-filter: blur(36px) saturate(160%); -webkit-backdrop-filter: blur(36px) saturate(160%);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-size: clamp(38px, 5vw, 70px); line-height: 1.02; letter-spacing: -1.4px; color: #16223a;
}
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #5b6a85; }

/* 卡片：更薄的玻璃，白边是唯一的结构线 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid rgba(255, 255, 255, 0.72); border-radius: 22px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.56), rgba(255, 255, 255, 0.26));
  box-shadow: 0 22px 48px -38px rgba(30, 46, 88, 0.5), inset 0 1px 0 #fff;
  backdrop-filter: blur(24px) saturate(150%); -webkit-backdrop-filter: blur(24px) saturate(150%);
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  border-color: rgba(77, 107, 255, 0.45); transform: translateY(-2px);
  box-shadow: 0 28px 55px -36px rgba(77, 107, 255, 0.55), inset 0 1px 0 #fff;
}
html[data-theme] .btn { border: 1px solid rgba(255, 255, 255, 0.8); border-radius: 999px; background: rgba(255, 255, 255, 0.62); color: #16223a; font-weight: 600; }
html[data-theme] .btn.primary { background: #3f5cf2; color: #fff; border-color: transparent; }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 30px 32px; border: 1px solid rgba(255, 255, 255, 0.8); border-radius: 28px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0.26));
  box-shadow: 0 32px 66px -46px rgba(30, 46, 88, 0.55), inset 0 1px 0 #fff;
  backdrop-filter: blur(34px) saturate(160%);
}
html[data-theme] #page-stats .page-head h1 { font-size: clamp(32px, 4.6vw, 56px); letter-spacing: -1.4px; color: #16223a; }
html[data-theme] #page-stats .eyebrow { color: var(--accent-ink); letter-spacing: 0.3em; }
html[data-theme] #page-stats .stat {
  border: 1px solid rgba(255, 255, 255, 0.8); border-radius: 22px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0.28));
  box-shadow: 0 20px 44px -34px rgba(30, 46, 88, 0.5), inset 0 1px 0 #fff;
  padding: 20px 22px; position: relative; overflow: hidden;
}
html[data-theme] #page-stats .stat:before {
  content: ""; position: absolute; inset: 0 auto 0 0; width: 2px;
  background: linear-gradient(180deg, #4d6bff, #ff9ec7); opacity: 0.7;
}
html[data-theme] #page-stats .stat label { font-size: 11px; letter-spacing: 0.16em; color: #5b6a85; text-transform: uppercase; }
html[data-theme] #page-stats .stat strong { font-size: 32px; font-weight: 700; letter-spacing: -1px; color: #16223a; background: none; -webkit-text-fill-color: #16223a; }
html[data-theme] #page-stats .stat em { color: #8492ab; }
html[data-theme] #page-stats .card { border-radius: 24px; padding: 22px; }
html[data-theme] #page-stats .section-title { border-bottom: 1px solid rgba(22, 34, 58, 0.08); }
html[data-theme] #page-stats .stat-bar { border-radius: 14px; background: rgba(255, 255, 255, 0.45); }
html[data-theme] #page-stats .stat-track { height: 7px; border-radius: 999px; background: rgba(22, 34, 58, 0.08); box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 999px; background: linear-gradient(90deg, #4d6bff, #ff9ec7); box-shadow: 0 2px 8px rgba(77, 107, 255, 0.35); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; padding: 28px 32px; border: 1px solid rgba(255, 255, 255, 0.82); border-radius: 28px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.28));
  box-shadow: 0 32px 66px -46px rgba(30, 46, 88, 0.55), inset 0 1px 0 #fff;
}
html[data-theme] #page-stats .year-title { font-size: 42px; letter-spacing: -1.4px; color: #16223a; background: none; -webkit-text-fill-color: #16223a; }
html[data-theme] #page-stats #echoYear { border: 1px solid rgba(255, 255, 255, 0.85); border-radius: 999px; background: rgba(255, 255, 255, 0.7); color: #16223a; }
html[data-theme] #page-stats #echoBody { padding: 24px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid rgba(255, 255, 255, 0.75); border-radius: 22px; background: rgba(255, 255, 255, 0.5); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid rgba(255, 255, 255, 0.75); border-radius: 14px; background: rgba(255, 255, 255, 0.6); color: #16223a;
}

/* 播放舱：白玻璃 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 1px solid rgba(255, 255, 255, 0.85); border-radius: 26px;
    background: linear-gradient(170deg, rgba(255, 255, 255, 0.66), rgba(255, 255, 255, 0.4));
    box-shadow: 0 30px 66px -36px rgba(30, 46, 88, 0.5), inset 0 1px 0 #fff;
    backdrop-filter: blur(34px) saturate(170%); -webkit-backdrop-filter: blur(34px) saturate(170%);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border-radius: 50%; background: #16223a; color: #fff; box-shadow: 0 10px 24px -14px rgba(22, 34, 58, 0.7); }
html[data-theme] .mini-player { border: 1px solid rgba(255, 255, 255, 0.8); border-radius: 20px; background: rgba(255, 255, 255, 0.6); box-shadow: 0 20px 40px -30px rgba(30, 46, 88, 0.45); }

html[data-theme] .cue.active .word { color: #0b1220; background: rgba(77, 107, 255, 0.16); border-radius: 4px; }
html[data-theme] ::-webkit-scrollbar-thumb { background: rgba(22, 34, 58, 0.22); border-radius: 999px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: linear-gradient(150deg, #eef2fa 0%, #e3eaf7 46%, #f4eef7 100%); color: #16223a; }
html[data-theme] .wp-bg { filter: blur(44px) saturate(70%) brightness(1.55) contrast(.9); opacity: .3; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(238,242,250,.9) 0%, rgba(238,242,250,.8) 52%, rgba(244,238,247,.68) 78%, rgba(238,242,250,.92) 100%), radial-gradient(72% 60% at 78% 16%, rgba(77,107,255,.16), transparent 66%); }
html[data-theme] .wp-kicker { color: var(--accent-ink); font-weight:600;letter-spacing:.22em; }
html[data-theme] .wp-title { color: #16223a; font-weight:600;letter-spacing:-.03em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(22,34,58,.66); }
html[data-theme] .wp-cue.active::before { background: #4d6bff; box-shadow: 0 0 24px rgba(77,107,255,.4); width:clamp(4px,.3vw,5px);border-radius:4px; }
html[data-theme] .wp-cue.active .wp-en { color: #16223a; text-shadow: 0 2px 20px rgba(22,34,58,.14); font-weight:600;letter-spacing:-.035em; }
html[data-theme] .wp-word.past { color: #16223a; }
html[data-theme] .wp-word.active { color: #20305c; background-image: linear-gradient(180deg, transparent 60%, rgba(77,107,255,.34) 60%, rgba(255,158,199,.24) 94%, transparent 94%); text-shadow: 0 0 20px rgba(77,107,255,.35); border-radius:4px; }
html[data-theme] .wp-zh { color: rgba(22,34,58,.6); font-weight:400; }
html[data-theme] .wp-label { color: rgba(22,34,58,.4); }
html[data-theme] .wpbtn { background: rgba(255,255,255,.6); border-color: rgba(255,255,255,.85); color: #16223a; border-radius:14px;backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px);box-shadow:0 14px 30px -18px rgba(22,34,58,.5),inset 0 1px 0 #fff; }
html[data-theme] .wpbtn:hover { background: rgba(77,107,255,.16); border-color: rgba(77,107,255,.5); color: #16223a; }
html[data-theme] .wp-shade::after { background-image: radial-gradient(rgba(22,34,58,.09) .6px, transparent .6px); background-size: 3px 3px; opacity:.7; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dstile {
  background: linear-gradient(168deg, rgba(255,255,255,.92), rgba(255,255,255,.62));
  border: 1px solid rgba(255,255,255,.9); border-radius: 16px;
  box-shadow: 0 10px 24px -18px rgba(40,60,110,.55), inset 0 1px 0 #fff;
  backdrop-filter: blur(16px) saturate(150%); -webkit-backdrop-filter: blur(16px) saturate(150%);
}
html[data-theme] .dstile:hover { border-color: var(--accent); box-shadow: 0 16px 30px -18px rgba(77,107,255,.45); }
html[data-theme] .dspill { border-radius: 999px; background: rgba(255,255,255,.8); border-color: rgba(77,107,255,.28); }
html[data-theme] .dsrange { accent-color: var(--accent); }

/* ---------- 可访问性收尾（2026-11-21，与液态玻璃同一套标准） ---------- */
/* 列表里的时长/时间点用等宽数字，12:04 与 1:02:04 的冒号能竖着对齐 */
html[data-theme] :where(.ep-dur, .dur, .time, .clock, .dst-time, .wp-time) {
  font-variant-numeric: tabular-nums;
}
/* 大标题与副标题防孤字 */
html[data-theme] :where(.page-head h1, .ledger-mast h1, .year-title, .page-head .subtitle) {
  text-wrap: balance;
}
/* 按下态：这套主题的按钮只有 hover，没有点击反馈 */
html[data-theme] :where(.btn, .icon-btn, .rail-toggle, .round-play, .sidebar-add, .nav button):active {
  transform: translateY(1px);
  filter: brightness(0.96);
}
/* 选中文字跟随主题强调色，别用系统蓝 */
html[data-theme] ::selection {
  background: color-mix(in srgb, var(--accent) 26%, transparent);
}
/* 基础样式已有全局 2px 焦点描边，这里只把圈收进来一点，避免被圆角切掉 */
html[data-theme] :where(button, [role="button"], [role="tab"], a[href]):focus-visible {
  outline-offset: 1px;
}
/* 尊重系统「减少动态效果」：漂移/闪烁/位移都是纯装饰，状态变化靠颜色与描边表达 */
@media (prefers-reduced-motion: reduce) {
  html[data-theme] *, html[data-theme] *::before, html[data-theme] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  html[data-theme] :where(.nav button, .pod-card, .continue, .stat, .dstile,
    .theme-card, .custom-card, .ep-row, .swatch):hover {
    transform: none !important;
  }
}

/* 玻璃主题的搜索药丸本身就是输入区边界，焦点挂在外壳上更清楚 */
html[data-theme] .search-global:focus-within {
  border-color: color-mix(in srgb, var(--accent) 55%, transparent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 25%, transparent);
}

/* 首页卡片内衬：底座把 .ledger-home .pod-card 的内距清零、封面出血；本主题给卡片描边后
   必须自己把字与按钮推回内衬里，否则贴边框；并让四张卡按钮同基线 */
html[data-theme] .ledger-home .pod-card { padding: 0 0 14px; overflow: hidden; }
html[data-theme] .ledger-home .pod-card .pod-card-main { flex: 1 1 auto; }
html[data-theme] .ledger-home .pod-card .pod-card-main > :not(.pod-art) { margin-left: 18px; margin-right: 18px; }
html[data-theme] .ledger-home .pod-card .pod-actions { margin: 12px 18px 0; }
